
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_mk00b_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_mk00b", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.275020240697482e+00, -1.704937849779972e+00, -2.230143292699412e+00, -2.818359731012656e+00, -3.383301660633482e+00, -3.767917896380669e+00, -3.765563568207017e+00, -3.224135068588112e+00, -2.228948083524774e+00, -1.192165603455646e+00, -5.627542254946685e-01, -4.434772892402397e-01, -6.359850115643770e-01, -6.080019044704668e-01, -3.501968283403354e-01, -1.355362715391042e-01, -6.504969622347892e-02, -5.983997433600140e-02, -5.349792313366027e-02, -4.094328274726673e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


